import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse each string as an int and return the sum.

    Raises BadInput carrying the first string that is not a valid integer.
    """
    total = 0
    for text in xs:
        try:
            total += int(text)
        except ValueError:
            raise BadInput(text) from None
    return total


def test_sum_parsed_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_signs() -> None:
    assert sum_parsed(["-3", "+4", "10"]) == 11


def test_sum_parsed_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["1", "x", "2"])
    assert excinfo.value.text == "x"


def test_sum_parsed_reports_first_bad_input() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["1", "abc", "def", "2"])
    assert excinfo.value.text == "abc"
